import dotenv from 'dotenv';
import fs from 'fs';
import path from 'path';

dotenv.config({ path: '.env.local' });

const apiKey = process.env.GOOGLE_GENAI_API_KEY;
if (!apiKey) {
  console.error("GOOGLE_GENAI_API_KEY is not set in .env.local!");
  process.exit(1);
}

const promptText = "A breathtaking, serene ocean landscape at sunset, cinematic lighting, warm golden hour, ultra high resolution, highly detailed photorealistic";

async function probe(model: string, body: any) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:predict`;
  console.log(`Probing: POST ${url}`);
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey as string
      },
      body: JSON.stringify(body)
    });

    console.log(`Response status for ${model}:predict: ${response.status}`);
    const text = await response.text();
    if (response.ok) {
      console.log(`SUCCESS on ${model}:predict!`);
      const data = JSON.parse(text);
      return data;
    } else {
      console.log(`Error body:`, text.substring(0, 1000));
    }
  } catch (err) {
    console.error(`Fetch error for ${model}:predict:`, err);
  }
  return null;
}

async function run() {
  const payload = {
    instances: [
      {
        prompt: promptText
      }
    ],
    parameters: {
      sampleCount: 1,
      aspectRatio: "16:9",
      outputMimeType: "image/jpeg"
    }
  };

  // Let's target the state-of-the-art 'imagen-4.0-generate-001'!
  let data = await probe('imagen-4.0-generate-001', payload);

  if (data) {
    saveImage(data);
    return;
  }
}

function saveImage(data: any) {
  console.log("Analyzing image response data keys:", Object.keys(data));
  const predictions = data.predictions || [];
  if (predictions.length === 0) {
    console.error("No predictions found in response!", JSON.stringify(data, null, 2));
    return;
  }

  const firstPrediction = predictions[0];
  const base64 = firstPrediction.bytesBase64Encoded;

  if (base64) {
    const dir = path.join(process.cwd(), 'public', 'molly-media');
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const filePath = path.join(dir, 'ocean_landscape.png');
    fs.writeFileSync(filePath, Buffer.from(base64, 'base64'));
    console.log(`\n🎉 IMAGE SAVED SUCCESSFULLY to ${filePath}`);
    console.log(`You can view it at: /molly-media/ocean_landscape.png\n`);
  } else {
    console.error("Could not find base64 image bytes in prediction:", JSON.stringify(firstPrediction, null, 2));
  }
}

run().catch(console.error);
